theorem numeric_head_separation {p q : Piece} {ps : List Piece} {n : NumLit}
    (h : noGlue (p :: q :: ps) = true) (hk : p.kind = .tok (.num n)) :
    (q.raw.head?.map isIdPart |>.getD false) = false

theorem classify_numeric {raw : Bytes} {n : NumLit}
    (h : classify .sol raw = some (.tok (.num n))) :
    Hexadecimal raw n ∨ Decimal raw n

theorem digits1_exact_suffix {raw ds rest : Bytes}
    (h : digits1 raw = some (ds, rest)) :
    ∃ pre : Bytes, raw = pre ++ rest ∧ eraseUnderscores pre = ds ∧ pre ≠ []

def readFraction : Bytes → Option (Bytes × Bytes)
  | 46 :: r => digits1 r
  | r => some ([], r)

theorem decimal_bad_exponent {raw ip r1 fp r2 : Bytes}
    (hi : IntegerPart raw ip r1) (hf : FractionPart r1 fp r2)
    (he : readExponent r2 = none) : decNumber raw = none

theorem decimal_exponent_underscore_refused {raw ip r1 fp rest : Bytes} {e : UInt8}
    (hi : IntegerPart raw ip r1) (hf : FractionPart r1 fp (e :: 95 :: rest))
    (he : e.toNat = 101 ∨ e.toNat = 69) : decNumber raw = none

theorem decimal_negative_exponent_underscore_refused {raw ip r1 fp rest : Bytes} {e : UInt8}
    (hi : IntegerPart raw ip r1) (hf : FractionPart r1 fp (e :: 45 :: 95 :: rest))
    (he : e.toNat = 101 ∨ e.toNat = 69) : decNumber raw = none

theorem decimal_plus_exponent_refused {raw ip r1 fp rest : Bytes} {e : UInt8}
    (hi : IntegerPart raw ip r1) (hf : FractionPart r1 fp (e :: 43 :: rest))
    (he : e.toNat = 101 ∨ e.toNat = 69) : decNumber raw = none

theorem FractionPart.erased_stop {raw ds rest : Bytes} {e : Int}
    (h : FractionPart raw ds rest) (he : Exponent rest e) :
    Tail (eraseUnderscores raw) [] (eraseUnderscores raw)

theorem FractionPart.erasure {raw ds rest : Bytes} {e : Int}
    (h : FractionPart raw ds rest) (he : Exponent rest e) :
    FractionPart (eraseUnderscores raw) ds (eraseUnderscores rest)

theorem IntegerPart.erasure {raw ds rest fp r2 : Bytes} {e : Int}
    (h : IntegerPart raw ds rest) (hf : FractionPart rest fp r2) (he : Exponent r2 e) :
    IntegerPart (eraseUnderscores raw) ds (eraseUnderscores rest)
